files.hooks/register.ts:
// htui-dev: developing htui. Guards that each refuse, with the fix in its reason, a kind of
// call that has cost this repo real work (docs/htui-dev.md):
//   G1  cargo test that builds feature-gated integration tests without their feature (0 tests, green)
//   G2  cargo test with the other crate's test feature name (testkit vs test-support)
//   G3  the literal extensibility.rs forbids, written into crates/**/*.{rs,json} by an edit tool
//   G4  file writes, and the git writes docs/htui-dev.md lists, from an agent started read-only
//   G5  a subagent asked to run on Fable
//   G6  git commit --no-verify (or -n), which skips the repo's commit hooks
// Every guard is a `{ deny }`, never a rewrite, and judges before `next`. A guard that throws
// lets the call through and says so on the status line (ANA-29 §6.3, "fail open"): the guards
// are a safety net, not a sandbox. Beside them (M2): one status line, refreshed by a 60 s timer in
// interactive sessions (item and HANDOFF phase, merge/ahead/dirty, disk, Postgres, last gate), a
// toast when a gate finishes, and the turnless /gate, /next and /validate. The mod runs git and
// the repo's scripts, reads HANDOFF.md and target/gate/last.json, writes no file and reaches no
// network. Its values in `$.state` (read-only agents' ids, the gate last toasted, whether the
// session runs the timer) survive a reload; the timer does not, and a tool call re-arms it.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'
import type { HtuiDevGateSeen, HtuiDevReadOnly, HtuiDevReadOnlyCalls } from '../types'
import { gateCommand, scriptArgv, scriptCommand, type Answer } from './commands'
import {
  composeAmbient,
  composeLine,
  gateToast,
  gather,
  join,
  parseGate,
  type GateRead,
  type Host,
  type Ran,
  type Reader,
  type Runner,
} from './status'
import {
  cargoTest,
  coarseGitWrite,
  type Cwd,
  declaresReadOnly,
  fableModel,
  forbiddenLiteral,
  gitWrite,
  isFable,
  movedTo,
  noVerify,
  readOnlyEdit,
  readOnlyGit,
  writesNothing,
} from './guards'
import { simpleCommands, type Words } from './shell'

const readOnly = atom({ plugin: 'htui-dev', key: 'readOnly' } as const, [] as HtuiDevReadOnly)
const readOnlyCalls = atom({ plugin: 'htui-dev', key: 'readOnlyCalls' } as const, [] as HtuiDevReadOnlyCalls)
const gateSeen = atom({ plugin: 'htui-dev', key: 'gateSeen' } as const, null as HtuiDevGateSeen | null)
const ambient = atom({ plugin: 'htui-dev', key: 'ambient' } as const, false as boolean)

/** The status timer's period (ANA-29 §6.1). */
const PERIOD_MS = 60_000
/** How long a guard warning leads the line, from the first tick that showed it. */
const WARNING_MS = 10 * 60_000

/** `status_line` as `register` read it; off stops the timer. */
let statusLine = true
/** The status timer while one runs; a module reload drops it. */
let timer: Timer | null = null
/** Set while a tick runs, so a slow tick is never overlapped by the next. */
let polling = false
/** Whether a tool call already asked `ambient` since this module loaded. */
let rearmChecked = false
/** The last guard warning, and the tick time it was first shown at (null until a tick stamps it). */
let warning: { text: string; at: number | null } | null = null
/** The last ambient line a tick composed. */
let ambientLine: string | null = null
/** The last line put on the status line, so an unchanged tick sends nothing. */
let shown: string | undefined
/** The checkout, found once per module load. */
let hostMemo: Host | null = null

/** Puts the composed line on the plugin's status line (`force`: even when unchanged); never throws. */
function show($: EngineInterface, force = false): void {
  const line = composeLine(warning?.text ?? null, ambientLine)
  if (!force && line === shown) return
  shown = line
  try {
    // Fire and forget: the call answers nothing, so only a throw (a re-entry) is seen.
    $.ui.status(line)
  } catch {
    // The next tick sends the line again.
    shown = undefined
  }
}

/**
 * Puts `text` on the plugin's status line, ahead of the ambient line while there is one; never
 * throws and calls nothing on `$` but the status line (it runs where every other `$` call rejects).
 */
function warn($: EngineInterface, text: string): void {
  warning = { text, at: null }
  show($, true)
}

/** Runs one guard; a throw is a status warning and no refusal (ANA-29 §6.3). */
function judge($: EngineInterface, guard: string, what: 'call' | 'spawn', decide: () => string | null): string | null {
  try {
    return decide()
  } catch {
    warn($, `htui-dev: ${guard} guard failed, ${what} allowed`)
    return null
  }
}

/**
 * Whether the list `load` reads holds `id`; an undefined or empty `id` reads nothing. A read that
 * fails, or a value that is no list, warns with `failed` and answers false.
 */
async function holds($: EngineInterface, load: () => Promise<unknown>, id: string | undefined, failed: string): Promise<boolean> {
  if (id === undefined || id === '') return false
  try {
    const ids = await load()
    if (!Array.isArray(ids)) throw new TypeError('the state holds no list')
    return ids.includes(id)
  } catch {
    warn($, failed)
    return false
  }
}

/** Whether `agentId` was tagged read-only. The main loop (no `agentId`) never reads the state. */
const isTagged = ($: EngineInterface, agentId: string | undefined, failed: string): Promise<boolean> =>
  holds($, () => read($, readOnly), agentId, failed)

/** Whether a read-only agent made the Workflow or Agent call `toolUseId`. */
const isReadOnlyCall = ($: EngineInterface, toolUseId: string | undefined, failed: string): Promise<boolean> =>
  holds($, () => read($, readOnlyCalls), toolUseId, failed)

/** The list with `id` added, once. */
const adding =
  (id: string) =>
  (ids: readonly string[] | undefined): readonly string[] =>
    (ids ?? []).includes(id) ? ids! : [...(ids ?? []), id]

/** Runs a state write; one that fails warns with `failed`. */
async function store($: EngineInterface, write: () => Promise<unknown>, failed: string): Promise<void> {
  try {
    await write()
  } catch {
    warn($, failed)
  }
}

/**
 * `agent.spawn`'s backstop (a throw, an overrun budget, a wrong answer shape): a spawn is never
 * refused here. A settled `next` is replayed, with a warning that the agent may have started before
 * its read-only tag was written; otherwise the spawn goes ahead, with a warning.
 */
export function spawnBackstop<E, R>($: EngineInterface, e: E, next: ((e: E) => R) & { readonly called: boolean }): R {
  if (next.called) {
    warn($, 'htui-dev: agent.spawn guard failed after the spawn, read-only tag may be missing')
    return next(e)
  }
  warn($, 'htui-dev: agent.spawn guard failed, spawn allowed')
  return next(e)
}

// ---- M2: the status line ----

/** The clock's time; 0 when it cannot be read. */
async function nowOf($: EngineInterface): Promise<number> {
  try {
    return await $.clock.now()
  } catch {
    return 0
  }
}

/** `$.process.run` as a Runner: a run that cannot start, or outlasts its bound, is `{ failed }`. */
const runnerOf =
  ($: EngineInterface): Runner =>
  async (argv, init) => {
    const started = await nowOf($)
    try {
      const r = await $.process.run(argv, init)
      return { exitCode: r.exitCode, stdout: r.stdout, stderr: r.stderr } satisfies Ran
    } catch {
      const elapsed = (await nowOf($)) - started
      return { failed: elapsed >= init.timeoutMs ? 'timed out' : 'not found' }
    }
  }

/** `$.fs.read` as a Reader: a missing or unreadable file is null. */
const readerOf =
  ($: EngineInterface): Reader =>
  async path => {
    try {
      const text = await $.fs.read(path)
      return typeof text === 'string' ? text : null
    } catch {
      return null
    }
  }

/**
 * The checkout this copy of the mod sits in: `git rev-parse --show-toplevel` from the plugin
 * folder, and whether this is Windows. Kept once found; a failure is tried again next time.
 */
async function hostOf($: EngineInterface): Promise<Host | null> {
  if (hostMemo !== null) return hostMemo
  const r = await runnerOf($)(['git', 'rev-parse', '--show-toplevel'], { cwd: $.plugin.root, timeoutMs: 10_000 })
  if ('failed' in r || r.exitCode !== 0 || r.stdout.trim() === '') return null
  let windows = false
  try {
    windows = (await $.env.get('OS')) === 'Windows_NT'
  } catch {
    // Not Windows, as far as anyone can tell.
  }
  hostMemo = { root: r.stdout.trim(), windows }
  return hostMemo
}

/** Toasts a gate that finished since the last one seen (C2); the first one seen only seeds. */
async function toastGate($: EngineInterface, doc: GateRead): Promise<void> {
  if (doc === null || doc === 'unreadable' || doc.state === 'running' || doc.finished === null) return
  const seen = await read($, gateSeen)
  if (seen !== null && seen.finished === doc.finished) return
  const finished = doc.finished
  const text = gateToast(doc)
  if (seen !== null && text !== null) $.ui.toast(text)
  await update($, gateSeen, () => ({ finished }))
}

/** Seeds `gateSeen` from the gate result there is now, so a gate that ended before the session never toasts. */
async function seedGate($: EngineInterface): Promise<void> {
  const host = await hostOf($)
  // No root, no seed: the first finished gate a tick sees then seeds instead of toasting.
  if (host === null) return
  const doc = parseGate(await readerOf($)(join(host.root, 'target', 'gate', 'last.json')))
  const finished = doc !== null && doc !== 'unreadable' && doc.state !== 'running' ? doc.finished : null
  await update($, gateSeen, prev => prev ?? { finished })
}

/** One period: gather the facts, compose the line, toast a finished gate, age the warning out. */
async function tick($: EngineInterface): Promise<void> {
  if (polling) return
  polling = true
  try {
    const now = await nowOf($)
    const host = await hostOf($)
    if (host === null) {
      ambientLine = 'htui-dev: no repo root (git rev-parse failed)'
    } else {
      let hrItem: string | undefined
      try {
        hrItem = await $.env.get('HR_ITEM')
      } catch {
        hrItem = undefined
      }
      const snap = await gather(host, hrItem, runnerOf($), readerOf($), scriptArgv(host, 'health'))
      ambientLine = composeAmbient(snap, now)
      try {
        await toastGate($, snap.gate)
      } catch {
        // The state store failed: no toast this time; the line still updates.
      }
    }
    if (warning !== null) {
      warning.at ??= now
      if (now - warning.at >= WARNING_MS) warning = null
    }
    show($)
  } catch {
    // The module unloaded mid-tick (its `$` is gone), or a state write failed: the next tick retries.
  } finally {
    polling = false
  }
}

/** Starts the status timer unless one runs, with one tick now. */
function arm($: EngineInterface): void {
  if (timer !== null) return
  timer = $.clock.every(PERIOD_MS, () => void tick($))
  void (async () => {
    try {
      await seedGate($)
    } catch {
      // Unseeded: the first finished gate seen then seeds instead of toasting.
    }
    await tick($)
  })()
}

/**
 * A reload drops the timer. Live (2.1.296) a reload raises `session.start` again, which re-arms
 * it; should one not, the first main-loop tool call after it asks `ambient` whether this session
 * ran the timer and re-arms it (or, with `status_line` now off, takes the ambient part off the
 * line). Never awaited: it adds nothing to a guard's path.
 */
function kick($: EngineInterface, agentId: string | undefined): void {
  // Only the main loop's calls: a subagent's `$` is not known to outlive its dispatch.
  if (agentId !== undefined || rearmChecked || timer !== null) return
  rearmChecked = true
  void (async () => {
    let fit: boolean
    try {
      fit = await read($, ambient)
    } catch {
      rearmChecked = false
      return
    }
    if (fit !== true) return
    if (statusLine) {
      arm($)
    } else {
      ambientLine = null
      show($, true)
    }
  })().catch(() => {})
}

// ---- M2: the commands ----

const NO_ROOT: Answer = { text: 'htui-dev: cannot find the repo root (git rev-parse --show-toplevel failed)', exitCode: 1 }

/** Runs a command's body against the checkout; never throws (a throw is the command's answer). */
async function answer($: EngineInterface, name: string, body: (h: Host) => Promise<Answer>): Promise<Answer> {
  try {
    const h = await hostOf($)
    return h === null ? NO_ROOT : await body(h)
  } catch (err) {
    return { text: `htui-dev: /${name} failed: ${err instanceof Error ? err.message : String(err)}`, exitCode: 1 }
  }
}

export const register: Register = (on, options) => {
  statusLine = (options as { status_line?: unknown }).status_line !== false
  timer = null
  polling = false
  rearmChecked = false
  warning = null
  ambientLine = null
  shown = undefined
  hostMemo = null

  on('session.start', async ($, e, next) => {
    // Every session gets the commands (they serve `claude -p "/validate"` too); each is registered
    // by a literal name, so `claude plugin validate` reads its hook as answering its own command.
    try {
      await $.command.register({
        name: 'gate',
        description: 'Run the htui gate detached (scripts/gate.sh); status: its last result',
        argumentHint: '[step|status|force]',
      })
      await $.command.register({ name: 'next', description: 'Rank the open HANDOFF items (next-item script)' })
      await $.command.register({ name: 'validate', description: 'Check HANDOFF.md and DECISIONS.md (workflow validator)' })
    } catch {
      warn($, 'htui-dev: /gate, /next or /validate not registered')
    }
    // The timer runs where a person watches the line, and never in a session htui drives.
    try {
      const fit = e.isInteractive === true && (await $.env.get('HTUI_SESSION')) === undefined
      await update($, ambient, () => fit)
      if (fit && statusLine) arm($)
    } catch {
      // No timer; the commands still work.
    }
    return next(e)
  })

  on('command.run', { command: 'gate' }, async ($, e) =>
    answer($, 'gate', async h => {
      const run = runnerOf($)
      const head = await run(['git', 'rev-parse', 'HEAD'], { cwd: h.root, timeoutMs: 10_000 })
      const sha = 'failed' in head || head.exitCode !== 0 ? null : head.stdout.trim()
      return gateCommand(e.args, h, run, readerOf($), await nowOf($), sha)
    }),
  )
  on('command.run', { command: 'next' }, async $ => answer($, 'next', h => scriptCommand('next', h, runnerOf($))))
  on('command.run', { command: 'validate' }, async $ => answer($, 'validate', h => scriptCommand('validate', h, runnerOf($))))

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    kick($, e.agentId)
    let cmds: Words[] | null = null
    try {
      cmds = simpleCommands(e.command)
    } catch {
      warn($, 'htui-dev: shell parser failed, call allowed')
    }
    const tagged = await isTagged($, e.agentId, 'htui-dev: read-only guard failed, call allowed')
    if (cmds === null) {
      // A line the parser cannot follow is allowed, with no status: it is no failure of the guard.
      // A read-only agent's still meets a coarse check for git writes.
      const reason = tagged
        ? judge($, 'read-only', 'call', () => {
            const verb = coarseGitWrite(e.command)
            return verb === null ? null : readOnlyGit(verb, e.agentId!)
          })
        : null
      return reason !== null ? { deny: reason } : next(e)
    }
    // A `cd crates/<member>` earlier in the line makes a bare `cargo test` select that member.
    let cwd: Cwd = []
    for (const words of cmds) {
      const reason =
        (tagged
          ? judge($, 'read-only', 'call', () => {
              const verb = gitWrite(words)
              return verb === null ? null : readOnlyGit(verb, e.agentId!)
            })
          : null) ??
        judge($, 'no-verify', 'call', () => noVerify(words)) ??
        judge($, 'cargo test', 'call', () => cargoTest(words, cwd))
      if (reason !== null) return { deny: reason }
      try {
        cwd = movedTo(words, cwd)
      } catch {
        cwd = []
      }
    }
    return next(e)
  }).catch(($, e, next) => {
    // A backstop (overrun budget, wrong answer shape, re-entry): it replays a settled `next`, and
    // otherwise lets the call through with a warning. It never refuses.
    if (next.called) return next(e)
    warn($, 'htui-dev: tool.call guard failed, call allowed')
    return next(e)
  })

  // The tools that write a file. Of Gortex's MCP tools (Q3): `edit_file`, `write_file`,
  // `edit_symbol`, `rename_symbol` and `batch_edit` by their schemas; `edit` and `refactor`, the
  // compact names, read the same way. Serena's write tools are configured machine-wide, so they
  // reach this repo too; its optional JetBrains ones are `jet_brains_*` in Serena 2.0.0 (the
  // shorter `jetbrains_*` is matched as well). `execute_shell_command` is left out: Serena's
  // claude-code context excludes it, and it is no file write. Either server may also come from a plugin (`mcp__plugin_<name>_<server>__`).
  // The patterns are written in the matcher, so that `claude plugin validate` lists them.
  on(
    'tool.call',
    {
      tool: [
        'Edit',
        'Write',
        'NotebookEdit',
        /^mcp__(plugin_[a-z0-9_-]+_)?gortex__(edit|edit_file|edit_symbol|batch_edit|rename_symbol|refactor|write_file)$/,
        /^mcp__(plugin_[a-z0-9_-]+_)?serena__(create_text_file|replace_content|replace_in_files|replace_symbol_body|insert_after_symbol|insert_before_symbol|rename_symbol|safe_delete_symbol|replace_lines|insert_at_line|delete_lines|jet_?brains_(?:rename|move|safe_delete|inline_symbol))$/,
      ],
    },
    async ($, e, next) => {
      kick($, e.agentId)
      const input = e as unknown as Readonly<Record<string, unknown>>
      if (writesNothing(e.tool, input)) return next(e)
      // G4 first: a read-only agent writes nothing, whatever the text.
      if (await isTagged($, e.agentId, 'htui-dev: read-only guard failed, call allowed')) {
        return { deny: readOnlyEdit(e.tool, e.agentId!) }
      }
      const reason = judge($, 'forbidden literal', 'call', () => forbiddenLiteral(e.tool, input))
      return reason !== null ? { deny: reason } : next(e)
    },
  ).catch(($, e, next) => {
    // A backstop (overrun budget, wrong answer shape, re-entry): it replays a settled `next`, and
    // otherwise lets the call through with a warning. It never refuses.
    if (next.called) return next(e)
    warn($, 'htui-dev: tool.call guard failed, call allowed')
    return next(e)
  })

  // G4 for workflows: a workflow agent's spawn names no parent, only the Workflow call that
  // started its run (its `tool_use_id`). A read-only agent's Workflow and Agent calls are noted
  // before they run, so the spawns they cause can be tagged. Never refuses.
  on('tool.call', { tool: ['Workflow', 'Agent'] }, async ($, e, next) => {
    kick($, e.agentId)
    if (await isTagged($, e.agentId, 'htui-dev: read-only guard failed, call allowed')) {
      const id = e.tool_use_id
      await store($, () => update($, readOnlyCalls, adding(id)), `htui-dev: read-only tag failed, call ${id} unrecorded`)
    }
    return next(e)
  }).catch(($, e, next) => {
    if (next.called) return next(e)
    warn($, 'htui-dev: tool.call guard failed, call allowed')
    return next(e)
  })

  on('agent.spawn', async ($, e, next) => {
    // Every refusal comes before `next`: a deny after it fails the hook (AgentSpawnResult).
    const fable = judge($, 'Fable', 'spawn', () => fableModel(e.model))
    if (fable !== null) return { deny: fable }
    let tag = false
    try {
      tag = declaresReadOnly(e)
    } catch {
      warn($, 'htui-dev: read-only guard failed, spawn allowed untagged')
    }
    if (!tag) tag = await isTagged($, e.parentAgentId, 'htui-dev: read-only guard failed, spawn allowed untagged')
    // A main-loop spawn that is no workflow agent reads no state.
    if (!tag && (e.workflow !== undefined || e.parentAgentId !== undefined)) {
      tag = await isReadOnlyCall($, e.tool_use_id, 'htui-dev: read-only guard failed, spawn allowed untagged')
    }
    const got = await next(e)
    if (got.deny !== undefined) return got
    if (tag && got.agentId !== undefined) {
      const id = got.agentId
      await store($, () => update($, readOnly, adding(id)), `htui-dev: read-only tag failed, agent ${id} untagged`)
    }
    // G5's gap: a model left unset resolves from the agent definition or the parent, after the
    // hook could refuse. Too late to deny (it fails the hook); say so instead.
    if (typeof got.model === 'string' && isFable(got.model)) {
      warn($, `htui-dev: subagent ${got.agentId ?? '(no id)'} resolved to Fable (${got.model}) — inherited or pinned in its agent definition`)
    }
    return got
  }).catch(spawnBackstop)
}

files.hooks/commands.ts:
// The turnless commands (TOOL-8 M2, docs/htui-dev.md): `/gate` starts TOOL-9's gate detached,
// `/next` and `/validate` run the workflow scripts. Each runs the `.ps1` through pwsh on Windows
// and the `.sh` through bash elsewhere (ANA-29 §6.3), and answers the script's own text and exit
// code. The runner and reader are injected, so the kit tests drive these without an engine.
import { age, gateStatusText, isFreshRun, join, parseGate, type Host, type Ran, type Reader, type Runner } from './status'

/** gate.sh's STEPS (and gate.ps1's ValidateSet), in lockstep. */
export const GATE_STEPS = ['fmt', 'clippy-all', 'clippy-bare', 'postgres', 'test', 'abort-grep', 'migrations', 'workflow-docs', 'plugin'] as const

/** What a command answers: its transcript text, and the exit code a `claude -p "/cmd"` run takes. */
export type Answer = { text: string; exitCode: number }

export type Script = 'next' | 'validate' | 'health'

/** Each script's path from the repo root, without its `.sh`/`.ps1`. */
const SCRIPTS: Record<Script, string> = {
  next: '.claude/skills/handoff-run/scripts/next-item',
  validate: '.claude/skills/handoff-run/scripts/validate-workflow-docs',
  health: 'scripts/dev-health',
}

/** How a script is started on this platform: `bash x.sh`, or `pwsh -NoProfile -File x.ps1`. */
const launch = (h: Host, path: string): string[] =>
  h.windows ? ['pwsh', '-NoProfile', '-File', join(h.root, `${path}.ps1`)] : ['bash', join(h.root, `${path}.sh`)]

/** A workflow script's argv; `next` and `validate` are told the repo root. */
export function scriptArgv(h: Host, s: Script): string[] {
  const root = s === 'health' ? [] : h.windows ? ['-RepoRoot', h.root] : ['--repo-root', h.root]
  return [...launch(h, SCRIPTS[s]), ...root]
}

/** The detached gate's argv, for one step or all. */
export function gateArgv(h: Host, step: string | null): string[] {
  const only = step === null ? [] : h.windows ? ['-Only', step] : ['--only', step]
  return [...launch(h, 'scripts/gate'), h.windows ? '-Detach' : '--detach', ...only]
}

/** A run as a command's answer: stdout, with stderr after it on a failure, and the exit code. */
export function answerOf(ran: Ran, what: string): Answer {
  if ('failed' in ran) return { text: `htui-dev: ${what} could not run: ${ran.failed}`, exitCode: 1 }
  let text = ran.stdout.trimEnd()
  if (ran.exitCode !== 0 && ran.stderr.trim() !== '') text = text === '' ? ran.stderr.trimEnd() : `${text}\n${ran.stderr.trimEnd()}`
  if (text === '') text = `(${what}: no output, exit ${ran.exitCode})`
  return { text, exitCode: exitCodeOf(ran.exitCode) }
}

/** An exit code `command.run` takes (a whole number 0-255; any other fails the hook): else 1. */
const exitCodeOf = (c: number): number => (Number.isInteger(c) && c >= 0 && c <= 255 ? c : 1)

/** gate.sh --detach returns at once; the bound only covers a launcher that hangs. */
const GATE_LAUNCH_MS = 30_000
/** next-item and the validator finish in about a second here. */
const SCRIPT_MS = 60_000

/**
 * `/gate [step|status|force]`. Bare or with a step: refuses while a gate started under 4 h ago is
 * running, else starts it detached. `force` starts the whole gate regardless. `status` prints the
 * last result. Exit codes follow gate.sh: 1 refused or no result, 2 usage.
 */
export async function gateCommand(args: string, h: Host, run: Runner, read: Reader, now: number, head: string | null): Promise<Answer> {
  const verb = args.trim().split(/\s+/)[0] ?? ''
  const doc = parseGate(await read(join(h.root, 'target', 'gate', 'last.json')))
  if (verb === 'status') return { text: gateStatusText(doc, head, now), exitCode: doc === null || doc === 'unreadable' ? 1 : 0 }
  const step = verb === '' || verb === 'force' ? null : verb
  if (step !== null && !(GATE_STEPS as readonly string[]).includes(step)) {
    return { text: `unknown step "${step}" - /gate [step|status|force]; steps: ${GATE_STEPS.join(', ')}`, exitCode: 2 }
  }
  if (verb !== 'force' && isFreshRun(doc, now) && doc !== null && doc !== 'unreadable') {
    const t = Date.parse(doc.started)
    const ago = Number.isNaN(t) ? '' : ` (started ${age(Math.max(0, Math.floor((now - t) / 1000)))} ago)`
    return { text: `gate already running${ago}: /gate status for progress, /gate force to start another`, exitCode: 1 }
  }
  return answerOf(await run(gateArgv(h, step), { cwd: h.root, timeoutMs: GATE_LAUNCH_MS }), 'gate')
}

/** `/next` and `/validate`: the script's text and exit code. */
export async function scriptCommand(s: 'next' | 'validate', h: Host, run: Runner): Promise<Answer> {
  return answerOf(await run(scriptArgv(h, s), { cwd: h.root, timeoutMs: SCRIPT_MS }), s === 'next' ? 'next-item' : 'validate-workflow-docs')
}

files.hooks/status.ts:
// The status line's facts (TOOL-8 M2, docs/htui-dev.md): which item and HANDOFF phase, the
// branch's merge/ahead/dirty state, the repo disk and the dev Postgres, the last gate result.
// Pure functions over text, and `gather`, which reads the facts through an injected runner and
// reader so the kit tests drive it without an engine. Nothing here throws on bad input: a fact
// that cannot be read is left out of the line.

/** One process run: how it exited, or why it never did (not found, timed out). */
export type Ran = { exitCode: number; stdout: string; stderr: string } | { failed: string }
/** Runs `argv` in `cwd`; never throws. */
export type Runner = (argv: readonly string[], init: { cwd: string; timeoutMs: number }) => Promise<Ran>
/** A file's text, or null when it is absent or unreadable; never throws. */
export type Reader = (path: string) => Promise<string | null>
/** The checkout the mod serves: its root (as git prints it) and whether this is Windows. */
export type Host = { root: string; windows: boolean }

/** `root` and `parts` joined with `/`, which Windows accepts too; a trailing separator on `root` is dropped. */
export const join = (root: string, ...parts: string[]): string => [root.replace(/[\\/]+$/, ''), ...parts].join('/')

/** Whether a run exited, and with 0. */
const succeeded = (r: Ran): r is { exitCode: number; stdout: string; stderr: string } => !('failed' in r) && r.exitCode === 0

/** A JSON object: not null, not a list. */
const isObject = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === 'object' && !Array.isArray(v)

/** `42s`, `5m`, `3h`, `2d`: the largest whole unit, as the htui plugin's own lines. */
export const age = (s: number): string =>
  s < 60 ? `${s}s` : s < 3600 ? `${Math.floor(s / 60)}m` : s < 86400 ? `${Math.floor(s / 3600)}h` : `${Math.floor(s / 86400)}d`

// ---- S1: the item ----

/**
 * The item the session works on: `HR_ITEM` when set, else the first `PREFIX-N` in the branch,
 * upper-cased, else the branch itself (`detached` for none). `key` is the HANDOFF ID, when there is one.
 */
export function itemOf(hrItem: string | undefined, branch: string | null): { label: string; key: string | null } {
  if (hrItem !== undefined && hrItem !== '') return { label: hrItem, key: hrItem }
  const m = branch === null ? null : /([A-Za-z]+-\d+)/.exec(branch)
  if (m !== null) {
    const key = m[1]!.toUpperCase()
    return { label: key, key }
  }
  return { label: branch ?? 'detached', key: null }
}

// ---- S2: the HANDOFF phase ----

/** What `phaseOf` reads: `<X> landed` from the last phase note, `open`, or `not open`. */
export type Phase = string

const escapeRegExp = (s: string): string => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

/** A checklist line of any item, open or closed: the end of the item before it. */
const ITEM_LINE = /^\s*[-*+]\s*\[[^\]]*\]\s*\*\*[A-Z]+-\d+/
const HEADING = /^#{1,6}\s/

/**
 * `key`'s phase from HANDOFF.md: the last `**Phase <X> landed` in its open checklist line and the
 * lines under it, up to the next item line or heading, as `<X> landed`; `open` with no phase note;
 * `not open` when the item has no open line.
 */
export function phaseOf(handoff: string, key: string): Phase {
  const lines = handoff.split(/\r?\n/)
  const open = new RegExp(`^- \\[ \\] \\*\\*${escapeRegExp(key)}(?![0-9])\\s*[-–—]`)
  const start = lines.findIndex(l => open.test(l))
  if (start === -1) return 'not open'
  let end = start + 1
  while (end < lines.length && !ITEM_LINE.test(lines[end]!) && !HEADING.test(lines[end]!)) end++
  let phase: string | null = null
  for (const m of lines.slice(start, end).join('\n').matchAll(/\*\*Phase\s+(\S+?)\s+landed\b/g)) phase = m[1]!
  return phase === null ? 'open' : `${phase} landed`
}

// ---- S4: the branch ----

export type Porcelain = { oid: string | null; head: string | null; ahead: number | null; dirty: number }

/**
 * `git status --porcelain=v2 --branch`: the commit, the branch (null when detached), the commits
 * ahead of the upstream (null with no upstream), and the entries that are changed, renamed,
 * unmerged or untracked.
 */
export function parsePorcelainV2(stdout: string): Porcelain {
  const p: Porcelain = { oid: null, head: null, ahead: null, dirty: 0 }
  for (const line of stdout.split(/\r?\n/)) {
    let m: RegExpExecArray | null
    if ((m = /^# branch\.oid (\S+)/.exec(line)) !== null) p.oid = m[1] === '(initial)' ? null : m[1]!
    else if ((m = /^# branch\.head (.+)$/.exec(line)) !== null) p.head = m[1] === '(detached)' ? null : m[1]!
    else if ((m = /^# branch\.ab \+(\d+) -\d+/.exec(line)) !== null) p.ahead = Number(m[1])
    else if (/^[12u?] /.test(line)) p.dirty++
  }
  return p
}

// ---- S5/S6: dev-health ----

export type PgState = 'up' | 'recovering' | 'down' | 'unknown'
export type Health = { usedPct: number | null; pg: PgState | null }

const PG_STATES: readonly string[] = ['up', 'recovering', 'down', 'unknown']

/** scripts/dev-health's JSON line; anything it cannot read is null. */
export function parseHealth(stdout: string): Health {
  let doc: unknown
  try {
    doc = JSON.parse(stdout)
  } catch {
    return { usedPct: null, pg: null }
  }
  if (!isObject(doc)) return { usedPct: null, pg: null }
  const pct = isObject(doc.disk) ? doc.disk.used_pct : undefined
  const state = isObject(doc.postgres) ? doc.postgres.state : undefined
  return {
    usedPct: typeof pct === 'number' && Number.isFinite(pct) ? pct : null,
    pg: typeof state === 'string' && PG_STATES.includes(state) ? (state as PgState) : null,
  }
}

// ---- S7: the gate ----

export type GateStep = { name: string; status: string; seconds: number }
export type GateDoc = {
  head: string
  started: string
  finished: string | null
  state: 'running' | 'passed' | 'failed'
  steps: GateStep[]
}
/** A parsed `last.json`: the document, null when there is none, or `unreadable`. */
export type GateRead = GateDoc | null | 'unreadable'

/** `target/gate/last.json` as gate.sh/.ps1 writes it; null text is no file. */
export function parseGate(text: string | null): GateRead {
  if (text === null) return null
  let doc: unknown
  try {
    doc = JSON.parse(text)
  } catch {
    return 'unreadable'
  }
  if (!isObject(doc)) return 'unreadable'
  const { head, started, finished, state, steps } = doc
  if (state !== 'running' && state !== 'passed' && state !== 'failed') return 'unreadable'
  if (!Array.isArray(steps)) return 'unreadable'
  return {
    head: typeof head === 'string' ? head : '',
    started: typeof started === 'string' ? started : '',
    finished: typeof finished === 'string' ? finished : null,
    state,
    steps: steps.filter(isObject).map(s => ({
      name: String(s.name ?? ''),
      status: String(s.status ?? ''),
      seconds: Math.max(0, Math.floor(Number(s.seconds) || 0)),
    })),
  }
}

/** ` 4m` for the seconds from `isoTime` to `now`, or nothing when the time does not parse. */
const since = (isoTime: string | null, now: number): string => {
  const t = isoTime === null ? NaN : Date.parse(isoTime)
  return Number.isNaN(t) ? '' : ` ${age(Math.max(0, Math.floor((now - t) / 1000)))}`
}

const failedSteps = (doc: GateDoc): string[] => doc.steps.filter(s => s.status === 'failed').map(s => s.name)

/**
 * The outcome alone: `gate passed`, `gate passed (2 skipped)`, `gate failed: test, abort-grep`, or
 * `gate running`. A finished pass of one step (`--only`) names it: `gate plugin passed` (or
 * `skipped`) is not the gate passing. Skips are named as gate.sh names them, so a green cannot
 * hide a missing check.
 */
const outcome = (doc: GateDoc): string => {
  if (doc.state === 'passed' && doc.steps.length === 1) return `gate ${doc.steps[0]!.name} ${doc.steps[0]!.status}`
  if (doc.state === 'passed') {
    const skipped = doc.steps.filter(s => s.status === 'skipped').length
    return skipped === 0 ? 'gate passed' : `gate passed (${skipped} skipped)`
  }
  if (doc.state !== 'failed') return `gate ${doc.state}`
  const failed = failedSteps(doc)
  return failed.length === 0 ? 'gate failed' : `gate failed: ${failed.join(', ')}`
}

/**
 * The gate's part of the line: `gate running 4m` (from its start), `gate passed 2h` or `gate
 * failed: test 40m` (from its end), `(older HEAD)` when it ran on another commit; null with no file.
 */
export function gateSummary(doc: GateRead, head: string | null, now: number): string | null {
  if (doc === null) return null
  if (doc === 'unreadable') return 'gate: last.json unreadable'
  const when = since(doc.state === 'running' ? doc.started : doc.finished, now)
  const older = head !== null && doc.head !== '' && doc.head !== head ? ' (older HEAD)' : ''
  return `${outcome(doc)}${when}${older}`
}

/** The toast for a finished gate; null while it runs. */
export const gateToast = (doc: GateDoc): string | null => (doc.state === 'running' ? null : outcome(doc))

/** How long a `running` result blocks `/gate`: a gate killed mid-run leaves one behind. */
export const FRESH_MS = 4 * 3600_000

/** Whether a gate is running and started under FRESH_MS ago. */
export function isFreshRun(doc: GateRead, now: number): boolean {
  if (doc === null || doc === 'unreadable' || doc.state !== 'running') return false
  // A start that does not parse cannot be aged: a damaged file never blocks /gate.
  const t = Date.parse(doc.started)
  return !Number.isNaN(t) && now - t < FRESH_MS
}

/** `/gate status`: the summary, then one line per step. */
export function gateStatusText(doc: GateRead, head: string | null, now: number): string {
  const summary = gateSummary(doc, head, now)
  if (summary === null) return 'no gate result yet'
  if (doc === null || doc === 'unreadable') return summary
  return [summary, ...doc.steps.map(s => `${s.name} ${s.status} ${age(s.seconds)}`)].join('\n')
}

// ---- the line ----

/** Every fact the line shows; null where it could not be read. */
export type Snapshot = {
  item: { label: string; key: string | null }
  phase: Phase | null
  merging: boolean
  ahead: number | null
  dirty: number | null
  health: Health
  gate: GateRead
  head: string | null
}

/** The disk use above which the line shows it (ANA-29 D6). */
const DISK_WARN_PCT = 90

/**
 * The ambient line, quiet parts dropped: `TOOL-8 M1 landed · merging · 2 ahead · 1 dirty ·
 * disk 93% · pg down · gate passed 2h`.
 */
export function composeAmbient(s: Snapshot, now: number): string {
  const parts = [s.phase === null ? s.item.label : `${s.item.label} ${s.phase}`]
  if (s.merging) parts.push('merging')
  if (s.ahead !== null && s.ahead > 0) parts.push(`${s.ahead} ahead`)
  if (s.dirty !== null && s.dirty > 0) parts.push(`${s.dirty} dirty`)
  if (s.health.usedPct !== null && s.health.usedPct > DISK_WARN_PCT) parts.push(`disk ${s.health.usedPct}%`)
  if (s.health.pg === 'recovering' || s.health.pg === 'down') parts.push(`pg ${s.health.pg}`)
  const gate = gateSummary(s.gate, s.head, now)
  if (gate !== null) parts.push(gate)
  return parts.join(' · ')
}

/** The plugin's one status line: a guard warning leads the ambient line; neither clears it. */
export function composeLine(warning: string | null, ambient: string | null): string | undefined {
  if (warning !== null && ambient !== null) return `⚠ ${warning} · ${ambient}`
  return warning ?? ambient ?? undefined
}

// ---- gathering ----

const GIT_MS = 10_000
const HEALTH_MS = 20_000

/**
 * Reads every fact at once. `healthArgv` runs scripts/dev-health for the platform. A piece that
 * fails is null; the item falls back to `?` when git could not say which branch this is.
 */
export async function gather(host: Host, hrItem: string | undefined, run: Runner, read: Reader, healthArgv: readonly string[]): Promise<Snapshot> {
  const init = { cwd: host.root, timeoutMs: GIT_MS }
  const [status, merge, health, handoff, gateText] = await Promise.all([
    run(['git', '--no-optional-locks', 'status', '--porcelain=v2', '--branch'], init),
    run(['git', 'rev-parse', '-q', '--verify', 'MERGE_HEAD'], init),
    run(healthArgv, { cwd: host.root, timeoutMs: HEALTH_MS }),
    read(join(host.root, 'HANDOFF.md')),
    read(join(host.root, 'target', 'gate', 'last.json')),
  ])
  const porcelain = succeeded(status) ? parsePorcelainV2(status.stdout) : null
  let ahead = porcelain?.ahead ?? null
  if (porcelain !== null && ahead === null && porcelain.head !== null && porcelain.head !== 'main') {
    const count = await run(['git', 'rev-list', '--count', 'main..HEAD'], init)
    const n = succeeded(count) ? Number(count.stdout.trim()) : NaN
    ahead = Number.isSafeInteger(n) ? n : null
  }
  const item =
    porcelain === null && (hrItem === undefined || hrItem === '') ? { label: '?', key: null } : itemOf(hrItem, porcelain?.head ?? null)
  return {
    item,
    phase: item.key !== null && handoff !== null ? phaseOf(handoff, item.key) : null,
    merging: succeeded(merge),
    ahead,
    dirty: porcelain?.dirty ?? null,
    health: succeeded(health) ? parseHealth(health.stdout) : { usedPct: null, pg: null },
    gate: parseGate(gateText),
    head: porcelain?.oid ?? null,
  }
}

files.hooks/guards.ts:
// The guards' decisions, pure: each reads plain words or a plain record and answers the deny
// reason (`htui-dev: <what> — <the fix>`), or null to let the call through. Nothing here calls
// `$`; register.ts wires them onto the events and catches what they throw.
import { quoteWords, type Words } from './shell'

// --- G1 and G2: cargo test -------------------------------------------------------------------

// The three tables below are copied from the manifests; a drift is TOOL-9's gate to catch
// (`cargo tree -e features` shows what cargo really turns on). Every feature is `<crate>/<name>`.

/**
 * The features each member declares, and what each forwards to: the `[features]` tables of
 * `crates/*\/Cargo.toml`. Only the forwards that reach a test feature are listed (`dep:` ones are not).
 */
const FEATURES: Readonly<Record<string, Readonly<Record<string, readonly string[]>>>> = {
  htui: { testkit: ['htui-store/test-support'] },
  'htui-agent': { 'test-support': ['htui-core/test-support'] },
  'htui-core': { demo: [], 'test-support': ['htui-core/demo'], sqlx: [] },
  'htui-mcp': {},
  'htui-orch': { 'test-support': ['htui-core/test-support', 'htui-agent/test-support'] },
  'htui-secrets': {},
  'htui-store': { demo: ['htui-core/demo'], 'test-support': ['htui-store/demo'], 'local-embed': [] },
  'htui-worker': { 'test-support': [] },
}

/**
 * What selecting a member for `cargo test` turns on by itself: the `features = [...]` of its
 * `[dependencies]` and, since a test build uses them, its `[dev-dependencies]` (only `demo` and
 * `test-support` listed). Cargo unifies them over every selected crate, so `-p htui-agent
 * -p htui-orch` builds the agent's own tests with `test-support`, and `-p htui-store` its own.
 */
const SELECTING: Readonly<Record<string, readonly string[]>> = {
  htui: [
    'htui-core/demo',
    'htui-store/demo',
    'htui-agent/test-support',
    'htui-orch/test-support',
    'htui-worker/test-support',
    'htui-store/test-support',
  ],
  'htui-orch': ['htui-core/test-support', 'htui-agent/test-support'],
  'htui-worker': [
    'htui-core/test-support',
    'htui-orch/test-support',
    'htui-agent/test-support',
    'htui-store/demo',
    'htui-store/test-support',
  ],
  'htui-mcp': [
    'htui-core/test-support',
    'htui-agent/test-support',
    'htui-orch/test-support',
    'htui-store/demo',
    'htui-store/test-support',
  ],
  'htui-store': ['htui-core/test-support', 'htui-store/test-support'],
}

/**
 * The features a member's integration tests are gated on (`#![cfg(feature = …)]` over
 * `crates/*\/tests`: htui 43 files on `testkit`; agent 4 and core 8 on `test-support`; store 3 on
 * `test-support` and 5 on `demo`). The first is the one a refusal suggests.
 */
const GATES: Readonly<Record<string, readonly string[]>> = {
  htui: ['testkit'],
  'htui-agent': ['test-support'],
  'htui-core': ['test-support'],
  'htui-store': ['test-support', 'demo'],
}

/** Every member's test feature, `testkit` or `test-support`, gated tests or not: G2 checks the spelling. */
const TEST_FEATURE: Readonly<Record<string, string>> = Object.fromEntries(
  Object.entries(FEATURES).flatMap(([crate, own]) =>
    ['testkit', 'test-support'].filter(f => own[f] !== undefined).map(f => [crate, f]),
  ),
)

/** The virtual root's members (`Cargo.toml` `[workspace]`): a run with no package selection tests them all. */
const MEMBERS = [
  'htui',
  'htui-agent',
  'htui-core',
  'htui-mcp',
  'htui-orch',
  'htui-secrets',
  'htui-store',
  'htui-worker',
] as const

/** The two test feature names; a third spelling is no business of G2's. */
const FEATURE_NAMES = new Set(['testkit', 'test-support'])

/** cargo's own options before the subcommand that take a value as the next word. */
const CARGO_GLOBAL_VALUE = new Set(['--color', '--config', '-Z', '-C', '--explain'])

/** `cargo test` options that take a value as the next word (beside the ones read below). */
const TEST_VALUE = new Set([
  '--target',
  '--target-dir',
  '-j',
  '--jobs',
  '--profile',
  '--color',
  '--config',
  '-Z',
  '--message-format',
  '--lockfile-path',
])

/** Target selectors that leave the integration tests out of the run. */
const OUT_OF_SCOPE = new Set(['--lib', '--bin', '--bins', '--doc', '--example', '--examples', '--bench', '--benches'])

/** Target selectors that bring them in. */
const IN_SCOPE = new Set(['--test', '--tests', '--all-targets'])

/** One `--features` value as written: the word it sits in and the text before it there (`--features=`, `-F`, or none). */
type FeatureWord = { index: number; prefix: string }

/** What a `cargo test` command asks for, read from its words. */
type CargoTest = {
  words: Words
  /** Selected packages (`-p`, `--manifest-path`), or null for the whole workspace. */
  packages: string[] | null
  excluded: string[]
  features: string[]
  featureWords: FeatureWord[]
  allFeatures: boolean
  /** Whether the run builds the integration tests (`--test`, `--tests`, `--all-targets`, or no selector). */
  inScope: boolean
  /** Where the test binary's own arguments start (`--`), or the words' length. */
  dashDash: number
  /** Whether `--workspace`/`--all` or `--manifest-path` says where to test, whatever the working directory. */
  located: boolean
}

/**
 * The package a `--manifest-path` names: its folder's name when that folder sits in `crates/` (or
 * `../`), or is a bare `<member>/Cargo.toml`; otherwise null, the workspace root, whatever its
 * folder is called (`/r/.claude/worktrees/tool-8/Cargo.toml`, `/home/me/htui/Cargo.toml`).
 */
function manifestPackage(path: string): string | null {
  const parts = path.replace(/\\/g, '/').split('/').filter(p => p !== '' && p !== '.')
  const name = parts[parts.length - 2]
  if (name === undefined) return null
  const above = parts[parts.length - 3]
  if (above === 'crates' || above === '..') return name
  const bare = above === undefined && !path.startsWith('/') && (MEMBERS as readonly string[]).includes(name)
  return bare ? name : null
}

/** `cargo test`'s short options that take a value, attached (`-phtui`) or as the next word. */
const SHORT_VALUE = new Set(['p', 'F', 'j', 'Z'])

/** The members a package spec names: `@version` dropped, a glob (`htui-*`) matched against the members, anything else as written. */
function packagesOf(spec: string): string[] {
  const name = spec.replace(/@.*$/, '')
  if (!/[*?[]/.test(name)) return [name]
  const pattern = name.replace(/[.+^${}()|\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\?/g, '.')
  return MEMBERS.filter(m => new RegExp(`^${pattern}$`).test(m))
}

/** Reads `words` as a `cargo test` (or `cargo t`) command, or null when it is none. */
function parseCargoTest(words: Words): CargoTest | null {
  if ((words[0] ?? '').split('/').pop() !== 'cargo') return null
  let at = 1
  while (at < words.length) {
    const w = words[at]!
    if (w.startsWith('+')) at++
    else if (CARGO_GLOBAL_VALUE.has(w)) at += 2
    else if (w.startsWith('-')) at++
    else break
  }
  if (words[at] !== 'test' && words[at] !== 't') return null

  const got: CargoTest = {
    words,
    packages: null,
    excluded: [],
    features: [],
    featureWords: [],
    allFeatures: false,
    inScope: true,
    dashDash: words.length,
    located: false,
  }
  let workspace = false
  let selectors = 0
  let inScopeSelectors = 0
  const packages: string[] = []
  const addFeatures = (index: number, prefix: string) => {
    got.featureWords.push({ index, prefix })
    got.features.push(...words[index]!.slice(prefix.length).split(/[\s,]+/).filter(f => f !== ''))
  }
  /** The value of option `name` at `i`: `name=v`, `-xv` (short), or the next word; `[value, words used]`. */
  const valueOf = (i: number, name: string): [string | undefined, number] => {
    const w = words[i]!
    if (w === name) return [words[i + 1], 2]
    return [w.startsWith('--') ? w.slice(name.length + 1) : w.slice(name.length), 1]
  }
  /** Whether `w` is option `name`, alone or with its value attached. */
  const isOpt = (w: string, name: string) =>
    w === name || (name.startsWith('--') ? w.startsWith(name + '=') : w.startsWith(name))

  for (let i = at + 1; i < words.length; ) {
    const w = words[i]!
    if (w === '--') {
      got.dashDash = i
      break
    }
    if (/^-[A-Za-z]/.test(w)) {
      // A short cluster (`-qp htui`, `-vvF testkit`): flags until one takes a value, which is the
      // rest of the cluster or the next word.
      let used = 1
      for (let j = 1; j < w.length; j++) {
        const letter = w[j]!
        if (!SHORT_VALUE.has(letter)) continue
        const attached = w.slice(j + 1)
        const value = attached !== '' ? attached : words[i + 1]
        if (attached === '') used = 2
        if (letter === 'p' && value !== undefined) packages.push(...packagesOf(value))
        if (letter === 'F' && value !== undefined) {
          if (attached !== '') addFeatures(i, w.slice(0, j + 1))
          else addFeatures(i + 1, '')
        }
        break
      }
      i += used
    } else if (isOpt(w, '--package')) {
      const [v, n] = valueOf(i, '--package')
      if (v !== undefined) packages.push(...packagesOf(v))
      i += n
    } else if (isOpt(w, '--manifest-path')) {
      const [v, n] = valueOf(i, '--manifest-path')
      const pkg = v === undefined ? null : manifestPackage(v)
      if (pkg !== null) packages.push(pkg)
      got.located = true
      i += n
    } else if (w === '--workspace' || w === '--all') {
      workspace = true
      got.located = true
      i++
    } else if (isOpt(w, '--exclude')) {
      const [v, n] = valueOf(i, '--exclude')
      if (v !== undefined) got.excluded.push(...packagesOf(v))
      i += n
    } else if (w === '--all-features') {
      got.allFeatures = true
      i++
    } else if (isOpt(w, '--features')) {
      if (w === '--features') {
        if (i + 1 < words.length) addFeatures(i + 1, '')
        i += 2
      } else {
        addFeatures(i, '--features=')
        i++
      }
    } else if (OUT_OF_SCOPE.has(w.split('=')[0]!) || IN_SCOPE.has(w.split('=')[0]!)) {
      const name = w.split('=')[0]!
      selectors++
      if (IN_SCOPE.has(name)) inScopeSelectors++
      // `--test <name>`, `--bin <name>`, ...: the name is the next word unless attached with `=`.
      const takesName = !w.includes('=') && ['--test', '--bin', '--example', '--bench'].includes(name)
      i += takesName && i + 1 < words.length && !words[i + 1]!.startsWith('-') ? 2 : 1
    } else if (TEST_VALUE.has(w)) {
      i += 2
    } else {
      i++
    }
  }
  got.packages = workspace || packages.length === 0 ? null : packages
  got.inScope = selectors === 0 || inScopeSelectors > 0
  return got
}

/**
 * The features (`<crate>/<name>`) a run of `t` over the crates `selected` turns on: the command
 * line's (`--all-features`; a plain name on each selected crate that has it; `<crate>/<name>`), what
 * selecting each crate turns on, and everything those forward to.
 */
function enabledFeatures(t: CargoTest, selected: readonly string[]): Set<string> {
  const queue: string[] = []
  for (const crate of selected) {
    const own = FEATURES[crate] ?? {}
    if (t.allFeatures) queue.push(...Object.keys(own).map(f => `${crate}/${f}`))
    for (const term of t.features) if (!term.includes('/') && own[term] !== undefined) queue.push(`${crate}/${term}`)
    queue.push(...(SELECTING[crate] ?? []))
  }
  queue.push(...t.features.filter(term => term.includes('/')))
  const on = new Set<string>()
  while (queue.length > 0) {
    const feature = queue.pop()!
    if (on.has(feature)) continue
    on.add(feature)
    const [crate, name] = feature.split('/') as [string, string]
    queue.push(...(FEATURES[crate]?.[name] ?? []))
  }
  return on
}

/** `a`, `a and b`, `a, b and c`. */
const listed = (items: readonly string[]): string =>
  items.length < 2 ? items.join('') : `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`

/** `t`'s words with `add` put before `--`, or at the end. */
const withWords = (t: CargoTest, add: readonly string[]): Words => [
  ...t.words.slice(0, t.dashDash),
  ...add,
  ...t.words.slice(t.dashDash),
]

/** G2: a test feature named for a crate that spells it the other way, with the command corrected. */
function wrongFeature(t: CargoTest): string | null {
  const selected = t.packages ?? [...MEMBERS]
  for (const term of t.features) {
    const slash = term.indexOf('/')
    const crate = slash === -1 ? null : term.slice(0, slash)
    const name = slash === -1 ? term : term.slice(slash + 1)
    if (!FEATURE_NAMES.has(name)) continue
    let owner: string | undefined
    if (crate !== null) {
      if (TEST_FEATURE[crate] !== undefined && TEST_FEATURE[crate] !== name) owner = crate
    } else if (!selected.some(c => TEST_FEATURE[c] === name)) {
      owner = selected.find(c => TEST_FEATURE[c] !== undefined)
    }
    if (owner === undefined) continue
    const right = TEST_FEATURE[owner]!
    const fixed = t.words.map((w, i) => {
      const fw = t.featureWords.find(f => f.index === i)
      if (fw === undefined) return w
      const swapped = w
        .slice(fw.prefix.length)
        .split(/([\s,]+)/)
        .map(part => (part === term ? (crate === null ? right : `${crate}/${right}`) : part))
        .join('')
      return fw.prefix + swapped
    })
    return `htui-dev: ${owner} has no \`${name}\` feature (cargo will refuse it) — it is \`${right}\`: ${quoteWords(fixed)}`
  }
  return null
}

/** G1: integration tests built without the feature they are gated on, so they run 0 tests and pass. */
function vacuousRun(t: CargoTest): string | null {
  if (!t.inScope) return null
  const selected = [...new Set(t.packages ?? MEMBERS.filter(c => !t.excluded.includes(c)))]
  const on = enabledFeatures(t, selected)
  const missing = selected.filter(c => (GATES[c] ?? []).some(f => !on.has(`${c}/${f}`)))
  if (missing.length === 0) return null
  // A plain name turns the feature on in every selected crate that has it, so one word fixes all.
  const features = [...new Set(missing.map(c => GATES[c]![0]!))]
  const tests = missing.length === 1 ? `${missing[0]}'s integration tests` : `the integration tests of ${listed(missing)}`
  const fix = quoteWords(withWords(t, ['--features', features.join(',')]))
  const single = t.packages !== null && selected.length === 1
  return `htui-dev: \`${quoteWords(t.words)}\` builds ${tests} without ${listed(features.map(f => `\`${f}\``))}, so they run 0 tests and pass — run: ${fix}${single ? '' : ' (or --all-features)'}`
}

/**
 * G1 and G2 over one simple command run in `cwd` (see `movedTo`): G2 first (its text is the more
 * precise), then G1. In a member's folder a `cargo test` that names no package, workspace or
 * manifest tests that member, as cargo finds its manifest first.
 */
export function cargoTest(words: Words, cwd: Cwd = []): string | null {
  const t = parseCargoTest(words)
  if (t === null) return null
  const member = memberAt(cwd)
  if (member !== null && t.packages === null && !t.located) t.packages = [member]
  return wrongFeature(t) ?? vacuousRun(t)
}

// --- The working directory a line moves to (G1) ------------------------------------------------

/**
 * The working directory, as far as the Bash line has told: its folders, relative to where the line
 * started (or from `/` after an absolute `cd`); [] for where it started, and for a place the line does
 * not tell. The session's own directory is not known, and read as no member's.
 */
export type Cwd = readonly string[]

/** The member whose folder `cwd` is in: the folder after a `crates` folder, when it names a member (cargo looks for the manifest from any folder below it). */
function memberAt(cwd: Cwd): string | null {
  for (let i = cwd.length - 2; i >= 0; i--) {
    if (cwd[i] === 'crates' && (MEMBERS as readonly string[]).includes(cwd[i + 1]!)) return cwd[i + 1]!
  }
  return null
}

/**
 * The working directory after the simple command `words`, run in `cwd`: a `cd` or `pushd` to a path
 * joins it onto `cwd` (an absolute one replaces it), `.` and `..` resolved. `cd` alone, `cd -`, `~`,
 * a `$VAR`, `pushd` with no folder or with `+N`/`-N`, and `popd` go where the line does not tell: [].
 * `pushd -n` and any other command leave `cwd` as it is.
 */
export function movedTo(words: Words, cwd: Cwd): Cwd {
  const program = words[0]
  if (program === 'popd') return []
  if (program !== 'cd' && program !== 'pushd') return cwd
  let at = 1
  for (; at < words.length && /^-[LPe@n]+$/.test(words[at]!); at++) {
    if (program === 'pushd' && words[at]!.includes('n')) return cwd
  }
  if (words[at] === '--') at++
  const dir = words[at]
  if (dir === undefined || /^[-+~]/.test(dir) || /[$`]/.test(dir)) return []
  return segmentsOf(dir.startsWith('/') ? dir : [...cwd, dir].join('/'))
}

// --- G6 and G4's Bash half: git ---------------------------------------------------------------

/** git's own options before the subcommand that take a value as the next word (`-C dir`, `--git-dir x`). */
const GIT_GLOBAL_VALUE = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace', '--exec-path', '--config-env'])

/** `git commit`'s short options whose value is the rest of the cluster or the next word. */
const COMMIT_SHORT_VALUE = new Set(['m', 'F', 'C', 'c', 't'])

/** `git commit`'s short options whose value, if any, is only the rest of the cluster (`-S<keyid>`, `-u<mode>`). */
const COMMIT_SHORT_OPTIONAL = new Set(['S', 'u'])

/** `git commit`'s long options that take the next word as their value when not given with `=`. */
const COMMIT_LONG_VALUE = new Set([
  '--message',
  '--file',
  '--reuse-message',
  '--reedit-message',
  '--template',
  '--author',
  '--date',
  '--fixup',
  '--squash',
  '--cleanup',
  '--trailer',
  '--pathspec-from-file',
])

/** `git commit`'s long options that take no value (2.43): an abbreviation of one is no value-taking option. */
const COMMIT_LONG_FLAG = [
  '--all',
  '--patch',
  '--interactive',
  '--amend',
  '--allow-empty',
  '--allow-empty-message',
  '--branch',
  '--dry-run',
  '--edit',
  '--include',
  '--long',
  '--no-edit',
  '--no-post-rewrite',
  '--no-verify',
  '--null',
  '--only',
  '--porcelain',
  '--quiet',
  '--reset-author',
  '--short',
  '--signoff',
  '--no-signoff',
  '--status',
  '--no-status',
  '--verbose',
  '--verify',
  '--gpg-sign',
  '--no-gpg-sign',
  '--untracked-files',
  '--pathspec-file-nul',
  '--ahead-behind',
  '--no-ahead-behind',
]

/** Whether long option `w` (no `=`) takes the next word: a value-taking option, or an abbreviation git reads as one alone. */
const takesValue = (w: string): boolean =>
  COMMIT_LONG_VALUE.has(w) ||
  (w.length > 3 && [...COMMIT_LONG_VALUE].some(o => o.startsWith(w)) && !COMMIT_LONG_FLAG.some(o => o.startsWith(w)))

/** The subcommand of a `git` command and where its arguments start, or null when `words` run no git. */
function gitSubcommand(words: Words): { sub: string; at: number } | null {
  if ((words[0] ?? '').split('/').pop() !== 'git') return null
  let at = 1
  while (at < words.length) {
    const w = words[at]!
    if (GIT_GLOBAL_VALUE.has(w)) at += 2
    else if (w.startsWith('-')) at++
    else return { sub: w, at: at + 1 }
  }
  return null
}

/** Whether a long option `w` is `full` or a prefix of it git would take (at least `min` characters). */
const abbreviates = (w: string, full: string, min: number): boolean => w.length >= min && full.startsWith(w)

/**
 * G6: `git commit` with `--no-verify` (or a prefix git takes) or `-n`, also inside a short-flag
 * cluster, unless a later `--verify` cancels it. The deny shows the commit without the flag.
 */
export function noVerify(words: Words): string | null {
  const git = gitSubcommand(words)
  if (git === null || git.sub !== 'commit') return null
  let skips = false
  const fixed: string[] = [...words.slice(0, git.at)]
  for (let i = git.at; i < words.length; i++) {
    const w = words[i]!
    if (w === '--') {
      fixed.push(...words.slice(i))
      break
    }
    if (w.startsWith('--')) {
      const name = w.split('=')[0]!
      if (abbreviates(name, '--no-verify', '--no-ve'.length) && !w.includes('=')) {
        skips = true
        continue
      }
      if (abbreviates(name, '--verify', '--veri'.length) && !w.includes('=')) skips = false
      fixed.push(w)
      if (!w.includes('=') && takesValue(w) && i + 1 < words.length) fixed.push(words[++i]!)
      continue
    }
    if (!w.startsWith('-') || w === '-') {
      fixed.push(w)
      continue
    }
    // A short cluster: letters until one takes a value, which is the rest or the next word.
    let kept = '-'
    let takesNext = false
    for (let j = 1; j < w.length; j++) {
      const letter = w[j]!
      if (COMMIT_SHORT_VALUE.has(letter)) {
        kept += w.slice(j)
        takesNext = j === w.length - 1
        break
      }
      if (COMMIT_SHORT_OPTIONAL.has(letter)) {
        kept += w.slice(j)
        break
      }
      if (letter === 'n') skips = true
      else kept += letter
    }
    if (kept !== '-') fixed.push(kept)
    if (takesNext && i + 1 < words.length) fixed.push(words[++i]!)
  }
  if (!skips) return null
  return `htui-dev: git commit --no-verify skips the repo's commit hooks — commit without it: ${quoteWords(fixed)}`
}

/** git subcommands that change the working tree, the index, refs, history or the remote in every form (G4). */
const GIT_WRITES = new Set([
  'commit',
  'reset',
  'restore',
  'merge',
  'rebase',
  'cherry-pick',
  'revert',
  'am',
  'pull',
  'push',
  'checkout-index',
  'read-tree',
  'update-ref',
  'update-index',
  'gc',
  'filter-branch',
])

/**
 * git subcommands that write only through some of their own subcommands: the action is the first
 * word that is no option (past the value of an option `skip` names), and `writes` says whether
 * that action (or none, `undefined`) writes. The label names the action when there is one to name.
 */
const GIT_ACTIONS: Readonly<Record<string, { skip: readonly string[]; writes: (action: string | undefined) => boolean; named: boolean }>> = {
  bisect: { skip: [], writes: a => !['log', 'view', 'visualize'].includes(a ?? ''), named: false },
  worktree: { skip: [], writes: a => ['add', 'remove', 'move', 'prune'].includes(a ?? ''), named: true },
  submodule: { skip: [], writes: a => ['update', 'deinit', 'add', 'sync'].includes(a ?? ''), named: true },
  'sparse-checkout': { skip: [], writes: a => a !== 'list', named: false },
  reflog: { skip: [], writes: a => a === 'expire' || a === 'delete', named: true },
  notes: { skip: ['--ref'], writes: a => ['add', 'remove', 'edit', 'append', 'copy', 'prune'].includes(a ?? ''), named: true },
}

/** The first word of `args` that is no option, past the value of an option in `skip`. */
function actionOf(args: Words, skip: readonly string[]): string | undefined {
  for (let i = 0; i < args.length; i++) {
    const w = args[i]!
    if (skip.includes(w)) i++
    else if (!w.startsWith('-')) return w
  }
  return undefined
}

/**
 * The long option `w` (its name before `=`) stands for among `options`: itself, or the one option
 * it is a prefix of, as git reads an abbreviation. Null for a `--no-` form, an unknown option, or an
 * ambiguous prefix (git refuses that one itself).
 */
function longOption(w: string, options: readonly string[]): string | null {
  const name = w.split('=')[0]!
  if (name.startsWith('--no-')) return null
  if (options.includes(name)) return name
  const hits = options.filter(o => o.startsWith(name))
  return hits.length === 1 ? hits[0]! : null
}

/** `git checkout`'s long options (2.43), for reading an abbreviation. */
const CHECKOUT_LONG = [
  '--guess',
  '--overlay',
  '--quiet',
  '--recurse-submodules',
  '--progress',
  '--merge',
  '--conflict',
  '--detach',
  '--track',
  '--force',
  '--orphan',
  '--overwrite-ignore',
  '--ignore-other-worktrees',
  '--ours',
  '--theirs',
  '--patch',
  '--ignore-skip-worktree-bits',
  '--pathspec-from-file',
  '--pathspec-file-nul',
]

/** `git switch`'s long options (2.43), for reading an abbreviation. */
const SWITCH_LONG = [
  '--create',
  '--force-create',
  '--guess',
  '--discard-changes',
  '--quiet',
  '--recurse-submodules',
  '--progress',
  '--merge',
  '--conflict',
  '--detach',
  '--track',
  '--force',
  '--orphan',
  '--overwrite-ignore',
  '--ignore-other-worktrees',
]

/** Long options of `checkout` and `switch` whose value is the next word when not given with `=`. */
const BRANCH_LONG_VALUE = ['--create', '--force-create', '--orphan', '--conflict', '--pathspec-from-file']

/**
 * What a `git checkout` or `git switch` writes, or null when it only switches (or creates) a branch.
 * `long` maps the long options that write to their label, `short` the short letters that do;
 * `shortValue` are the letters whose value is the rest of the cluster or the next word. For
 * checkout, a second positional or `.` is a pathspec.
 */
function branchWrite(
  sub: 'checkout' | 'switch',
  args: Words,
  options: readonly string[],
  long: Readonly<Record<string, string>>,
  short: Readonly<Record<string, string>>,
  shortValue: string,
): string | null {
  let positionals = 0
  for (let i = 0; i < args.length; i++) {
    const w = args[i]!
    if (w === '--') return sub === 'checkout' ? 'git checkout <paths>' : null
    if (w.startsWith('--')) {
      const o = longOption(w, options)
      if (o === null) continue
      if (long[o] !== undefined) return `git ${sub} ${long[o]}`
      if (BRANCH_LONG_VALUE.includes(o) && !w.includes('=')) i++
      continue
    }
    if (/^-[A-Za-z0-9]/.test(w)) {
      // A short cluster: flags until one takes a value, which is the rest or the next word.
      for (let j = 1; j < w.length; j++) {
        const letter = w[j]!
        if (short[letter] !== undefined) return `git ${sub} ${short[letter]}`
        if (shortValue.includes(letter)) {
          if (j === w.length - 1) i++
          break
        }
      }
      continue
    }
    if (sub === 'checkout' && (w === '.' || ++positionals >= 2)) return 'git checkout <paths>'
  }
  return null
}

/** What `git checkout` writes, or null when it only switches branches: paths (also `--ours`/`--theirs`, `-2`/`-3`), `--force` or `--patch`. */
const checkoutWrite = (args: Words): string | null =>
  branchWrite(
    'checkout',
    args,
    CHECKOUT_LONG,
    { '--force': '--force', '--patch': '--patch', '--ours': '<paths>', '--theirs': '<paths>', '--pathspec-from-file': '<paths>' },
    { f: '--force', p: '--patch', '2': '<paths>', '3': '<paths>' },
    'bB',
  )

/** What `git switch` writes, or null when it only switches or creates a branch: `--force`/`--discard-changes`, `-C`, `--orphan`. */
const switchWrite = (args: Words): string | null =>
  branchWrite(
    'switch',
    args,
    SWITCH_LONG,
    { '--force': '--force', '--discard-changes': '--discard-changes', '--force-create': '--force-create', '--orphan': '--orphan' },
    { f: '--force', C: '--force-create' },
    'c',
  )

/** `git clean`'s long options (2.43), for reading an abbreviation. */
const CLEAN_LONG = ['--quiet', '--dry-run', '--force', '--interactive', '--exclude']

/**
 * Whether a `git clean` is a dry run: `-n` (also in a short cluster, before an `-e` whose value is
 * the rest of it) or `--dry-run` (or a prefix git takes), before `--` and not as an exclude pattern.
 */
function cleanDryRun(args: Words): boolean {
  for (let i = 0; i < args.length; i++) {
    const w = args[i]!
    if (w === '--') return false
    if (w.startsWith('--')) {
      const o = longOption(w, CLEAN_LONG)
      if (o === '--dry-run') return true
      if (o === '--exclude' && !w.includes('=')) i++
    } else if (/^-[A-Za-z]/.test(w)) {
      for (let j = 1; j < w.length; j++) {
        if (w[j] === 'n') return true
        if (w[j] === 'e') {
          if (j === w.length - 1) i++
          break
        }
      }
    }
  }
  return false
}

/** The `git apply` options that turn applying off: they only read the patch. */
const APPLY_READS = ['--check', '--stat', '--numstat', '--summary']

/** Whether a `git apply` only reads: at least one of `APPLY_READS`, and no other option. */
function applyReadsOnly(args: Words): boolean {
  let reads = false
  for (const w of args) {
    if (w === '--') break
    if (APPLY_READS.includes(w)) reads = true
    else if (w.startsWith('-') && w !== '-') return false
  }
  return reads
}

/** Whether a `git add`, `mv` or `rm` is a dry run: `-n` (none of their short options takes a value) or a prefix of `--dry-run`, before `--`. */
function dryRun(args: Words): boolean {
  for (const w of args) {
    if (w === '--') return false
    if (w.startsWith('--') ? w.length >= 3 && '--dry-run'.startsWith(w) : /^-[A-Za-z]*n/.test(w)) return true
  }
  return false
}

/**
 * Whether a `git branch` or `git tag` command only lists: no write option (`writeLong`, or a short
 * cluster with a letter of `writeShort`), and a name given only to a list form (`--list`, `-l`, ...),
 * as a pattern, or as the value of a filter (`--contains <commit>`).
 */
function listsOnly(args: Words, writeLong: readonly string[], writeShort: string, listing: readonly string[]): boolean {
  const filters = ['--contains', '--no-contains', '--merged', '--no-merged', '--points-at', '--sort', '--format']
  let list = false
  let names = false
  for (let i = 0; i < args.length; i++) {
    const w = args[i]!
    const name = w.split('=')[0]!
    if (w === '--') {
      names ||= i + 1 < args.length
      break
    }
    if (writeLong.includes(name)) return false
    if (listing.includes(name)) list = true
    else if (filters.includes(w) && i + 1 < args.length && !args[i + 1]!.startsWith('-')) i++
    else if (/^-[A-Za-z]/.test(w) && !w.startsWith('--')) {
      const letters = w.slice(1).replace(/\d+$/, '')
      if ([...letters].some(l => writeShort.includes(l))) return false
      if ([...letters].some(l => listing.includes(`-${l}`))) list = true
    } else if (!w.startsWith('-')) names = true
  }
  return list || !names
}

/**
 * G4's Bash half: the git command, of those listed in docs/htui-dev.md, that changes the working
 * tree, the index, refs, history or the remote, as a label for the refusal, or null. Reading stays
 * allowed: status, diff, log, show, blame, fetch, `stash list|show`, `checkout <branch>`, `clean -n`,
 * the list forms of `branch`, `tag`, `replace`, `reflog`, `notes`, `worktree`, `submodule`,
 * `sparse-checkout`, and `bisect log|view|visualize`. A git command not listed passes (Known gaps).
 */
export function gitWrite(words: Words): string | null {
  const git = gitSubcommand(words)
  if (git === null) return null
  const args = words.slice(git.at)
  if (GIT_WRITES.has(git.sub)) return `git ${git.sub}`
  const actions = GIT_ACTIONS[git.sub]
  if (actions !== undefined) {
    const action = actionOf(args, actions.skip)
    if (!actions.writes(action)) return null
    return actions.named ? `git ${git.sub} ${action}` : `git ${git.sub}`
  }
  switch (git.sub) {
    case 'replace':
      // `git replace` alone, or with `-l`/`--list`, lists the replacements.
      return args.length === 0 || args[0] === '-l' || args[0] === '--list' || args[0]!.startsWith('--format') ? null : 'git replace'
    case 'stash':
      return args[0] === 'list' || args[0] === 'show' ? null : 'git stash'
    case 'checkout':
      return checkoutWrite(args)
    case 'switch':
      return switchWrite(args)
    case 'clean':
      return cleanDryRun(args) ? null : 'git clean'
    case 'apply':
      return applyReadsOnly(args) ? null : 'git apply'
    case 'add':
    case 'mv':
    case 'rm':
      return dryRun(args) ? null : `git ${git.sub}`
    case 'branch':
      return listsOnly(
        args,
        ['--delete', '--move', '--copy', '--force', '--set-upstream-to', '--unset-upstream', '--edit-description', '--track', '--no-track', '--create-reflog'],
        'dDmMcCfut',
        ['--list', '-l', '-a', '--all', '-r', '--remotes', '--show-current'],
      )
        ? null
        : 'git branch'
    case 'tag':
      return listsOnly(
        args,
        ['--annotate', '--sign', '--no-sign', '--local-user', '--force', '--delete', '--message', '--file', '--edit', '--create-reflog', '--trailer'],
        'asudmFfe',
        ['--list', '-l', '-n', '--verify', '-v'],
      )
        ? null
        : 'git tag'
    default:
      return null
  }
}

/**
 * A `git` word followed, past its global options, by a subcommand that writes in (nearly) every
 * form, or by a writing action of one that does not. Only for a line the parser cannot follow;
 * coarse on purpose.
 */
const COARSE_GIT_WRITE =
  /(?:^|[\s;&|()`'"])git(?:\s+(?:-C|-c|--git-dir|--work-tree|--namespace)\s+\S+|\s+-\S+)*\s+(commit|reset|restore|merge|rebase|cherry-pick|revert|am|apply|add|rm|mv|pull|clean|push|checkout-index|read-tree|update-ref|update-index|gc|filter-branch|stash(?!\s+(?:list|show)\b)|bisect(?!\s+(?:log|view|visualize)\b)|worktree\s+(?:add|remove|move|prune)|submodule\s+(?:update|deinit|add|sync)|sparse-checkout(?!\s+list\b)|reflog\s+(?:expire|delete)|notes\s+(?:add|remove|edit|append|copy|prune))(?![\w-])/

/**
 * G4's Bash half for a line the parser cannot follow (an unbalanced quote, a heredoc with no
 * end): the git write it seems to run, by a coarse pattern, or null. For a read-only agent only;
 * any other caller's unreadable line stays allowed.
 */
export function coarseGitWrite(command: string): string | null {
  const m = COARSE_GIT_WRITE.exec(command)
  return m === null ? null : `git ${m[1]!.replace(/\s+/g, ' ')}`
}

// --- G3: the forbidden literal --------------------------------------------------------------

/**
 * The name `crates/htui-agent/tests/extensibility.rs` forbids anywhere in `crates/**\/*.{rs,json}`
 * (case-sensitive), built so that this file never spells it.
 */
export const LITERAL = 'ze' + 'ta'

/**
 * The fields that carry the text a write puts into a file (Gortex: `new_string`, `new_source`,
 * `content`, `new_name`; Serena: `body`, `repl`, `content`, `new_name`); the old text is never read
 * (removing the literal is the fix).
 */
const NEW_TEXT = ['new_string', 'new_source', 'content', 'new_name', 'body', 'repl'] as const

/** Serena's one write tool that reaches many files: `relative_path` is a file, a folder, or empty for the whole project. */
const SERENA_MANY = /^mcp__(plugin_[a-z0-9_-]+_)?serena__replace_in_files$/

/** A path from a Gortex symbol id: what stands before `::` (`htui/crates/x.rs::Sym`). */
const idPath = (v: unknown): string | null => (typeof v === 'string' && v.includes('::') ? v.slice(0, v.indexOf('::')) : null)

/** The file a node of a tool's input names: `file_path`, `path`, `notebook_path`, `relative_path` (Serena), `target.file`, or a symbol id's file. */
function pathOf(node: Readonly<Record<string, unknown>>): string | null {
  for (const key of ['file_path', 'path', 'notebook_path', 'relative_path']) {
    if (typeof node[key] === 'string') return node[key] as string
  }
  const target = node.target
  if (target !== null && typeof target === 'object' && !Array.isArray(target)) {
    const t = target as Record<string, unknown>
    if (typeof t.file === 'string') return t.file
    const p = idPath(t.symbol) ?? idPath(t.id)
    if (p !== null) return p
  }
  return idPath(node.id)
}

/** A path's folders and file, `\\` read as `/`, with `.` dropped and `..` taken back. */
function segmentsOf(path: string): string[] {
  const out: string[] = []
  for (const part of path.replace(/\\/g, '/').split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..' && out.length > 0 && out[out.length - 1] !== '..') out.pop()
    else out.push(part)
  }
  return out
}

/**
 * Whether the literal scan reads `path`: a `.rs` or `.json` below the first `crates` folder, with
 * no `target` folder below it, and not the scan's own file `crates/htui-agent/tests/extensibility.rs`.
 */
function scanned(path: string): boolean {
  const parts = segmentsOf(path)
  const at = parts.indexOf('crates')
  if (at === -1 || at >= parts.length - 1) return false
  if (!/\.(rs|json)$/.test(parts[parts.length - 1]!)) return false
  if (parts.slice(at).includes('target')) return false
  return parts.slice(-4).join('/') !== 'crates/htui-agent/tests/extensibility.rs'
}

/** The first path, walking `node` with the nearest path passed down, whose new text holds the literal. */
function offender(node: unknown, inherited: string | null, depth: number): string | null {
  if (depth > 16 || node === null || typeof node !== 'object') return null
  if (Array.isArray(node)) {
    for (const item of node) {
      const hit = offender(item, inherited, depth + 1)
      if (hit !== null) return hit
    }
    return null
  }
  const record = node as Readonly<Record<string, unknown>>
  const path = pathOf(record) ?? inherited
  if (path !== null && scanned(path)) {
    for (const key of NEW_TEXT) {
      const v = record[key]
      if (typeof v === 'string' && v.includes(LITERAL)) return path
    }
  }
  for (const [key, v] of Object.entries(record)) {
    if (key === 'target') continue
    const hit = offender(v, path, depth + 1)
    if (hit !== null) return hit
  }
  return null
}

/** Whether a `replace_in_files` over `path` (a file, a folder, or empty for the whole project) can reach a file the scan reads. */
function reachesScanned(path: string): boolean {
  const parts = segmentsOf(path)
  if (parts.length === 0) return true
  if (/\.[A-Za-z0-9]+$/.test(parts[parts.length - 1]!)) return scanned(path)
  const at = parts.indexOf('crates')
  return at !== -1 && !parts.slice(at).includes('target')
}

/** A call that writes nothing although its tool can: Serena's `replace_in_files` as a dry run. */
export const writesNothing = (tool: string, input: Readonly<Record<string, unknown>>): boolean =>
  SERENA_MANY.test(tool) && input.dry_run === true

/** G3: an edit by `tool` that would write the literal into a file the scan reads; every matched tool's input is read the same way. */
export function forbiddenLiteral(tool: string, input: Readonly<Record<string, unknown>>): string | null {
  if (writesNothing(tool, input)) return null
  if (SERENA_MANY.test(tool)) {
    const where = typeof input.relative_path === 'string' ? input.relative_path : ''
    if (typeof input.repl !== 'string' || !input.repl.includes(LITERAL) || !reachesScanned(where)) return null
    const across = where.replace(/^\.?\/?$/, '') === '' ? 'the whole project' : where
    return `htui-dev: replacing across ${across} would write "${LITERAL}" into crates/**/*.{rs,json}, which crates/htui-agent/tests/extensibility.rs forbids — use another name, or narrow relative_path to files the scan does not read`
  }
  const path = offender(input, null, 0)
  if (path === null) return null
  return `htui-dev: ${path} would contain "${LITERAL}", which crates/htui-agent/tests/extensibility.rs forbids in crates/**/*.{rs,json} — use another name; only extensibility.rs may spell it`
}

// --- G4 and G5: subagents ---------------------------------------------------------------------

/** Agent types that review or design and never change the tree (Q2). A plugin's `<plugin>:<name>` counts by its name. */
const READ_ONLY_TYPES = new Set(['rust-reviewer', 'code-architect'])

/**
 * G4's marker (Q2): a prompt holding `READ-ONLY` (case-sensitive: a lowercase "read-only host tree"
 * is ordinary text) or "strictly no edits" (any case), or a read-only agent type. A tagged parent
 * is register.ts's to check: it lives in `$.state`.
 */
export function declaresReadOnly(spawn: { prompt: string; subagentType: string }): boolean {
  return (
    spawn.prompt.includes('READ-ONLY') ||
    /strictly no edits/i.test(spawn.prompt) ||
    READ_ONLY_TYPES.has(spawn.subagentType.split(':').pop()!)
  )
}

/** G4's deny for a file-writing tool called by the read-only agent `agentId`. */
export const readOnlyEdit = (tool: string, agentId: string): string =>
  `htui-dev: agent ${agentId} was started read-only and may not change files (${tool}) — report the change in your answer instead`

/** G4's deny for a git write (`gitWrite`'s label) run by the read-only agent `agentId`. */
export const readOnlyGit = (verb: string, agentId: string): string =>
  `htui-dev: agent ${agentId} was started read-only and may not run ${verb} — report what to change instead`

/** Whether a model name, alias or id, is a Fable model. */
export const isFable = (model: string): boolean => /fable/i.test(model)

/**
 * G5: a subagent asked to run on Fable. It reads the Agent tool's `model` parameter only: a model
 * left unset is resolved after the hook, from the agent definition or the parent (see register.ts).
 */
export function fableModel(model: string | undefined): string | null {
  if (model === undefined || !isFable(model)) return null
  return `htui-dev: subagents never run on Fable in this repo (model "${model}") — leave model unset so the agent inherits the session's model`
}

